<script setup lang="ts">
import { RouterLink, useRoute } from 'vue-router';
import { Text } from '@/shared/ui/text/paragraph';
import { computed } from 'vue';

interface Props {
    data: {
        name: string;
        link: string;
    }[]
}

const { data } = defineProps<Props>();
const route = useRoute();

// Функция для проверки активного маршрута
const isActive = (link: string) => {
    return route.path === link || route.path.startsWith(link + '/');
};
</script>

<template>
    <aside class="sidebar">
        <div class="list-items">
            <RouterLink 
                v-for="(item, index) in data" 
                :key="index" 
                :to="item.link" 
                :class="['item', { 'item-active': isActive(item.link) }]"
            >
                <Text tagName="span" size="m" color="dark-first">
                    {{ item.name }}
                </Text>
            </RouterLink>
        </div>
        <RouterLink to="/solutions/" class="aside-link">
            <img src="../../../assets/images/aside.png" alt="">
        </RouterLink>
        <Text tagName="p" size="m" color="dark-gray2">
            Завод «Молмаш» ваш надежный партнер в реализации производственных задач
        </Text>
    </aside>
</template>

<style lang="scss" scoped>
@import './style.scss';
</style>